// V(key, name, title, face, voice, accent, lair, captive [mood, line], lines [intro, hook, spit1, spit2, down, gloat], baby [name, mischief, emoji, extra])
// lair: [name, skyTop, skyBottom, far, sides, floor, fx, deco, music]
function V(key, name, title, face, voice, accent, lair, captive, lines, baby) {
  const [chain, contract, id, collection, label, traits] = VILLAIN_NFTS[key];
  const [lname, top, bottom, far, sides, floor, fx, deco, music] = lair;
  return {
    key, name, title, face, voice, accent,
    nft: { chain, contract, id, collection, label, traits },
    lair: { name: lname, sky: [top, bottom], far, sides, floor, fx, deco: [...deco], music },
    captive: { mood: captive[0], line: captive[1] },
    lines: { intro: lines[0], hook: lines[1], spit: [lines[2], lines[3]], down: lines[4], gloat: lines[5] },
    baby: { name: baby[0], mischief: baby[1], emoji: baby[2], extra: baby[3] || null },
  };
}

